  // 4. First update: change name to "Marketing Team" — generates first 'updated' snapshot
  const updatedDept1 =
    await api.functional.hrmTimeTracking.member.departments.update(
      memberConnection,
      {
        departmentId: department.id,
        body: {
          name: "Marketing Team",
        },
