export async function test_api_task_history_retrieval_by_project_lead(
  connection: api.IConnection,
): Promise<void> {
  // 1. Join as a new member to get authenticated connection
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {});
  const employeeId = authorized.employees[0].id;
  // 2. Create a project
  const project =
    await generate_random_hrm_time_tracking_member_projects_create(
      memberConnection,
      {},
    );
  typia.assert(project);
  // 3. Add the authenticated employee as a project-lead
  await generate_random_hrm_time_tracking_member_projects_members_create(
    memberConnection,
    {
      body: {
        employee_id: employeeId,
        role: "project-lead",
      } satisfies IHrmTimeTrackingProjectMember.ICreate,
      params: {
        projectId: project.id,
      },
    },
  );
  // 4. Create a task within the project (initial status will be 'open')
  const task =
    await generate_random_hrm_time_tracking_member_projects_tasks_create(
      memberConnection,
      {
        params: {
          projectId: project.id,
        },
      },
    );
  typia.assert(task);
  // 5. Change the task status from 'open' to 'in-progress'
  // This automatically creates an immutable history entry
  const updatedTask =
    await api.functional.hrmTimeTracking.member.projects.tasks.status.updateStatus(
      memberConnection,
      {
        projectId: project.id,
        taskId: task.id,
        body: {
          status: "in-progress",
        } satisfies IHrmTimeTrackingTask.IUpdateStatus,
      },
    );
  typia.assert(updatedTask);
  // Get the history id from the updated task's taskHistories
  const historyId = updatedTask.taskHistories[0].id;
  // 6. Retrieve the specific history entry
  const history =
    await api.functional.hrmTimeTracking.member.projects.tasks.histories.at(
      memberConnection,
      {
        projectId: project.id,
        taskId: task.id,
        historyId,
      },
    );
  typia.assert(history);
  // Validation
  TestValidator.equals(
    "previous status should be 'open'",
    history.previous_status,
    "open",
  );
  TestValidator.equals(
    "new status should be 'in-progress'",
    history.new_status,
    "in-progress",
  );
  TestValidator.equals(
    "employee should reference authenticated employee",
    history.employee.id,
    employeeId,
  );
  TestValidator.equals("task id should match", history.task.id, task.id);
  TestValidator.equals(
    "task title should match",
    history.task.title,
    task.title,
  );
  TestValidator.predicate("created_at should be present and valid", () => {
    const date = new Date(history.created_at);
    return !isNaN(date.getTime());
  });
}

