export async function test_api_timelog_view_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new member
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {});
  typia.assert(authorized);
  // 2. Create an organization (the creator becomes an Owner employee automatically)
  const organization =
    await generate_random_hrm_time_tracking_member_organizations_create(
      memberConnection,
      {},
    );
  typia.assert(organization);
  // 3. Retrieve the authenticated employee's employee_id from the employees list
  const employeePage = await api.functional.hrmTimeTracking.employees.index(
    memberConnection,
    {
      body: {
        page: 1,
        limit: 1,
      } satisfies IHrmTimeTrackingEmployee.IRequest,
    },
  );
  typia.assert(employeePage);
  const employee = employeePage.data[0]!;
  typia.assert(employee);
  // 4. Create a project within the organization
  const project =
    await generate_random_hrm_time_tracking_member_projects_create(
      memberConnection,
      {},
    );
  typia.assert(project);
  // 5. Add the employee as a project member with role='member'
  const projectMember =
    await generate_random_hrm_time_tracking_member_projects_members_create(
      memberConnection,
      {
        params: {
          projectId: project.id,
        },
        body: {
          employee_id: employee.id,
          role: "member" as const,
        },
      },
    );
  typia.assert(projectMember);
  // 6. Create a timelog against the project
  const durationMinutes = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<30> & tags.Maximum<120>
  >();
  const timelog =
    await generate_random_hrm_time_tracking_member_timelogs_create(
      memberConnection,
      {
        body: {
          project_id: project.id,
          duration_minutes: durationMinutes,
          billable: true,
        },
      },
    );
  typia.assert(timelog);
  // 7. Retrieve the timelog by its ID
  const retrievedTimelog =
    await api.functional.hrmTimeTracking.member.timelogs.at(memberConnection, {
      timelogId: timelog.id,
    });
  typia.assert(retrievedTimelog);
  // 8. Validate the response
  TestValidator.equals(
    "employee.id matches",
    retrievedTimelog.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "project.id matches",
    retrievedTimelog.project.id,
    project.id,
  );
  TestValidator.equals(
    "durationMinutes matches",
    retrievedTimelog.durationMinutes,
    durationMinutes,
  );
  TestValidator.equals("billable is true", retrievedTimelog.billable, true);
  TestValidator.predicate(
    "timesheet is null",
    retrievedTimelog.timesheet === null,
  );
}

