export async function test_api_timesheet_submit_with_timelogs(
  connection: api.IConnection,
): Promise<void> {
  // ---- Setup ----
  // 1. Register a new member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {});
  // 2. Create an organization
  const organization =
    await generate_random_hrm_time_tracking_member_organizations_create(
      memberConnection,
      {},
    );
  typia.assert(organization);
  // 3. Create a project
  const project =
    await generate_random_hrm_time_tracking_member_projects_create(
      memberConnection,
      {},
    );
  typia.assert(project);
  // 4. Add the employee as a project member with role 'member'
  const projectMember =
    await generate_random_hrm_time_tracking_member_projects_members_create(
      memberConnection,
      {
        body: {
          role: "member",
        },
        params: {
          projectId: project.id,
        },
      },
    );
  typia.assert(projectMember);
  // 5. Create a timelog (120 min, Wednesday 2026-04-22)
  const timelog =
    await generate_random_hrm_time_tracking_member_timelogs_create(
      memberConnection,
      {
        body: {
          project_id: project.id,
          duration_minutes: 120,
          date: "2026-04-22T10:00:00.000Z",
        },
      },
    );
  typia.assert(timelog);
  // 6. Create a draft timesheet (Monday 2026-04-20)
  const timesheet =
    await generate_random_hrm_time_tracking_member_timesheets_create(
      memberConnection,
      {
        body: {
          week_start_date: "2026-04-20",
        },
      },
    );
  typia.assert(timesheet);
  // ---- Execution ----
  const submitted =
    await api.functional.hrmTimeTracking.member.timesheets.update(
      memberConnection,
      {
        timesheetId: timesheet.id,
        body: {} satisfies IHrmTimeTrackingTimesheet.IUpdate,
      },
    );
  typia.assert(submitted);
  // ---- Validation ----
  TestValidator.equals("timesheet status", submitted.status, "submitted");
  TestValidator.predicate(
    "submittedAt is present",
    () => submitted.submittedAt !== null && submitted.submittedAt !== undefined,
  );
  TestValidator.equals("total hours", submitted.totalHours, 2.0);
  TestValidator.predicate(
    "timelogs are included",
    () => submitted.timelogs.length >= 1,
  );
}

