    await api.functional.hrmTimeTracking.member.available_permissions.at(
      memberConnection,
    );
  typia.assert(output);
  // 3. Verify the permission code is one of the 9 valid system codes
  const VALID_CODES = [
    "org:manage",
    "employee:manage",
    "employee:view",
    "project:manage",
    "project:view",
    "time:manage",
    "time:approve",
    "time:view_all",
    "report:view",
  ] as const;
  TestValidator.predicate(
