      deleted_at: null,
    },
    select: {
      id: true,
      hrm_time_tracking_project_id: true,
    },
  });
  // Step 2: Get the project's organization for scoping
  const project =
    await MyGlobal.prisma.hrm_time_tracking_projects.findFirstOrThrow({
      where: {
        id: props.projectId,
        deleted_at: null,
      },
      select: {
        id: true,
